import Status from "../../components/Status";
import FullPresent from "../../components/FullPresent";
import BentoCard from "../../components/BentoCard";
import ClassicScroll from "../../components/ClassicScroll";
import "../../sass/_frames.scss";
import "../../sass/_grid.scss";
import {
  saknUrls,
  sakOverview,
  sakProjectStatus,
  realTimeInventory,
  workFlow,
} from "../../constrains/data";

export default function ManageCRM() {
  const { projectName, title, desc } = sakOverview;
  const { title01, desc01, img01 } = realTimeInventory;
  const { title02, desc02, img02 } = workFlow;

  return (
    <>
      <div className="compact-page">
        <FullPresent
          projectName={projectName}
          title={title}
          desc={desc}
          liveUrls={saknUrls}
          padding={"24px 0"}
        />
        <div className="container">
          <div className="mt-3">
            <div className="row justify-content-between mt-3 mt-md-5">
              {sakProjectStatus.map((item, index) => (
                <div key={index} className="col-sm-12 col-lg-3 pe-0 mb-5">
                  <Status title={item.title} collection={item.collection} />
                </div>
              ))}
            </div>
          </div>
          <div className="grid gap-4">
            <div className="cell-12 cell-lg-8">
              <BentoCard title={title01} desc={desc01} img={img01} />
            </div>
            <div className="cell-12 cell-lg-4">
              <BentoCard title={title02} desc={desc02} img={img02} />
            </div>
          </div>
        </div>
      </div>
    </>
  );
}
